function seed(
  question: string,
  correct: string,
  wrong: [string, string, string],
  explanation: string
): QuestionSeed {
  return { question, correct, wrong, explanation };
}

export const cryptoQuizQuestions: CryptoQuizQuestion[] = difficulties.flatMap((difficulty) =>
  questionLevels[difficulty].map((question, index) => ({
    id: `l${difficulty}-q${index + 1}`,
    difficulty,
    question: question.question,
    options: [question.correct, ...question.wrong],
    correctAnswer: question.correct,
    explanation: question.explanation
  }))
);

export const quizQuestionCount = cryptoQuizQuestions.length;
